// 自動生成: npm run sync-templates(../templates から)。手で編集しない。
export const TEMPLATES: Record<string, string> = {
  ".github/kban/resolve.js": "// Shared by kban workflows (actions/github-script).\n// Finds the kban issue behind a PR / commit and moves its kban:<stage> label forward.\nconst ORDER = [\"backlog\", \"ready\", \"building\", \"testing\", \"deploying\", \"verifying\", \"done\"];\n\nfunction linkedIssue(body, branch) {\n  const m = /(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\\s+#(\\d+)/i.exec(body || \"\");\n  if (m) return Number(m[1]);\n  const b = /issue-(\\d+)/.exec(branch || \"\");\n  return b ? Number(b[1]) : null;\n}\n\nasync function prFromSha({ github, context }, sha) {\n  const { owner, repo } = context.repo;\n  const { data } = await github.rest.repos.listPullRequestsAssociatedWithCommit({ owner, repo, commit_sha: sha });\n  return data.find((p) => p.state === \"open\") || data[0] || null;\n}\n\n/** Move the issue linked to `pr` to `stage` (forward only, except explicit backward moves by the board). */\nasync function moveFromPr({ github, context, core }, pr, stage, marker) {\n  if (!pr) return core.info(\"PR が見つかりません\");\n  const n = linkedIssue(pr.body, pr.head && pr.head.ref);\n  if (!n) return core.info(`PR #${pr.number} に kban の Issue が紐付いていません`);\n  return moveIssue({ github, context, core }, n, stage, marker);\n}\n\nasync function moveIssue({ github, context, core }, n, stage, marker) {\n  const { owner, repo } = context.repo;\n  const { data: issue } = await github.rest.issues.get({ owner, repo, issue_number: n });\n  const names = issue.labels.map((l) => (typeof l === \"string\" ? l : l.name));\n  if (!names.includes(\"kban\")) return core.info(`#${n} は kban のカードではありません`);\n  const cur = Math.max(0, ...names.map((l) => ORDER.indexOf(String(l).replace(/^kban:/, \"\"))));\n  if (ORDER.indexOf(stage) <= cur) return core.info(`#${n} はすでに ${ORDER[cur]} です`);\n\n  const labels = names.filter((l) => !ORDER.some((s) => l === `kban:${s}`)).concat(`kban:${stage}`);\n  let body = issue.body || \"\";\n  if (marker) {\n    body = body.replace(new RegExp(`\\\\n?<!-- kban:${marker.key}=.*? -->`, \"g\"), \"\");\n    body += `\\n<!-- kban:${marker.key}=${marker.value} -->`;\n  }\n  await github.rest.issues.update({ owner, repo, issue_number: n, labels, body });\n  core.info(`#${n}: ${ORDER[cur]} → ${stage}`);\n  return n;\n}\n\n/**\n * Add what Claude Code just used to the card (<!-- kban:tokens=… --> / cost). `file` is claude-code-action's\n * execution_file: a JSON array (or JSON lines) of messages whose last `result` has usage and total_cost_usd.\n * tokens = input + output + cache creation (cache reads are cheap and left out).\n */\nasync function recordUsage({ github, context, core }, file) {\n  const fs = require(\"fs\");\n  if (!file || !fs.existsSync(file)) return core.info(\"実行ログがないので使用量は記録しません\");\n  const raw = fs.readFileSync(file, \"utf8\");\n  let msgs;\n  try { msgs = JSON.parse(raw); } catch { msgs = raw.split(\"\\n\").filter(Boolean).map((l) => JSON.parse(l)); }\n  const r = [].concat(msgs).reverse().find((m) => m && m.type === \"result\");\n  if (!r || !r.usage) return core.info(\"結果に使用量がありません\");\n  const u = r.usage;\n  const tokens = (u.input_tokens || 0) + (u.output_tokens || 0) + (u.cache_creation_input_tokens || 0);\n  const cost = Number(r.total_cost_usd || 0);\n\n  const { owner, repo } = context.repo;\n  let n = context.issue && context.issue.number;\n  if (context.eventName === \"pull_request_review_comment\" || (context.payload.issue && context.payload.issue.pull_request)) {\n    const { data: pr } = await github.rest.pulls.get({ owner, repo, pull_number: n });\n    n = linkedIssue(pr.body, pr.head.ref);\n  }\n  if (!n) return core.info(\"紐付く Issue がないので使用量は記録しません\");\n  const { data: issue } = await github.rest.issues.get({ owner, repo, issue_number: n });\n  const get = (k) => Number((new RegExp(`<!-- kban:${k}=(.*?) -->`).exec(issue.body || \"\") || [])[1]) || 0;\n  // 直近5時間・7日の集計用に「秒:トークン」の履歴も残す(8日より古いものは捨てる)\n  const now = Math.floor(Date.now() / 1000);\n  const prev = ((/<!-- kban:usage=(.*?) -->/.exec(issue.body || \"\") || [])[1] || \"\").split(\",\").filter(Boolean)\n    .filter((e) => now - Number(e.split(\":\")[0]) < 8 * 86400);\n  const usage = [...prev, `${now}:${tokens}`].join(\",\");\n  let body = (issue.body || \"\").replace(/\\n?<!-- kban:(tokens|cost|usage)=.*? -->/g, \"\");\n  body += `\\n<!-- kban:tokens=${get(\"tokens\") + tokens} -->\\n<!-- kban:cost=${(get(\"cost\") + cost).toFixed(2)} -->\\n<!-- kban:usage=${usage} -->`;\n  await github.rest.issues.update({ owner, repo, issue_number: n, body });\n  core.info(`#${n}: +${tokens} tokens, +$${cost.toFixed(2)}`);\n}\n\nmodule.exports = { recordUsage, linkedIssue, prFromSha, moveFromPr, moveIssue, ORDER };\n",
  ".github/workflows/kban-ci.ios.yml": "# kban: iOS の CI(シミュレータでテスト)。名前 kban-ci を変えると kban-flow が追えなくなります。\nname: kban-ci\n\non:\n  pull_request:\n  push:\n    branches: [main]\n\njobs:\n  test:\n    runs-on: macos-15\n    timeout-minutes: 45\n    steps:\n      - uses: actions/checkout@v4\n      - name: Test\n        run: |\n          SCHEME=$(jq -r .scheme .github/kban/config.json)\n          DEST=\"platform=iOS Simulator,name=$(jq -r '.simulator // \"iPhone 16\"' .github/kban/config.json)\"\n          set -o pipefail\n          xcodebuild test -scheme \"$SCHEME\" -destination \"$DEST\" CODE_SIGNING_ALLOWED=NO | xcbeautify\n",
  ".github/workflows/kban-ci.web.yml": "# kban: Web の CI。名前 kban-ci を変えると kban-flow が追えなくなります。\nname: kban-ci\n\non:\n  pull_request:\n  push:\n    branches: [main]\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - run: npm run lint --if-present\n      - run: npm run typecheck --if-present\n      - run: npm test --if-present\n      - run: npm run build --if-present\n",
  ".github/workflows/kban-claude.yml": "# kban: Issue に `claude` ラベルが付いたら Claude Code が実装して PR を作る。\n# PR / Issue への `@claude` コメント(kban の「AIに差し戻す」)でも修正を続ける。\nname: kban-claude\n\non:\n  issues:\n    types: [labeled]\n  issue_comment:\n    types: [created]\n  pull_request_review_comment:\n    types: [created]\n\npermissions:\n  contents: write\n  pull-requests: write\n  issues: write\n  id-token: write\n  actions: read\n\nconcurrency:\n  group: kban-claude-${{ github.event.issue.number || github.event.pull_request.number }}\n  cancel-in-progress: false\n\njobs:\n  claude:\n    if: >-\n      (github.event_name == 'issues' && github.event.label.name == 'claude') ||\n      (github.event_name != 'issues' && contains(github.event.comment.body, '@claude'))\n    runs-on: __RUNNER__\n    timeout-minutes: 60\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - name: kban → 実装中\n        if: github.event_name == 'issues'\n        uses: actions/github-script@v7\n        with:\n          script: |\n            const k = require(`${process.env.GITHUB_WORKSPACE}/.github/kban/resolve.js`);\n            await k.moveIssue({ github, context, core }, context.issue.number, \"building\");\n\n      - uses: anthropics/claude-code-action@v1\n        id: claude\n        with:\n          # どちらか一方を Secrets に設定(Claude の契約なら claude setup-token で発行した OAuth トークン)\n          claude_code_oauth_token: ${{ secrets.CLAUDE_CODE_OAUTH_TOKEN }}\n          anthropic_api_key: ${{ secrets.ANTHROPIC_API_KEY }}\n          label_trigger: claude\n          trigger_phrase: \"@claude\"\n          claude_args: >-\n            --max-turns 80\n            --allowedTools \"Bash(git:*),Bash(gh pr create:*),Bash(gh pr view:*),Bash(gh pr comment:*),__TOOLS__\"\n\n      # 使った量を Issue に記録する(kban が「目安」と「今月の使用量」に使う)。失敗しても実装には影響しない\n      - name: kban → 使用量を記録\n        if: always()\n        continue-on-error: true\n        uses: actions/github-script@v7\n        env:\n          EXEC_FILE: ${{ steps.claude.outputs.execution_file }}\n        with:\n          script: |\n            const k = require(`${process.env.GITHUB_WORKSPACE}/.github/kban/resolve.js`);\n            await k.recordUsage({ github, context, core }, process.env.EXEC_FILE);\n",
  ".github/workflows/kban-flow.yml": "# kban: PR・CI・デプロイの進み具合に合わせて Issue の kban:<工程> ラベルを自動で進める。\n#   PR が開く            → テスト\n#   kban-ci が成功     → デプロイ\n#   プレビューのデプロイ成功(Firebase Hosting など) → 確認(プレビューURLを記録)\n#   PR がマージ          → 完了\nname: kban-flow\n\non:\n  pull_request:\n    types: [opened, reopened, ready_for_review, closed]\n  workflow_run:\n    workflows: [kban-ci]\n    types: [completed]\n  deployment_status:\n\npermissions:\n  issues: write\n  pull-requests: read\n  contents: read\n\njobs:\n  move:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          sparse-checkout: .github/kban\n          ref: ${{ github.event.repository.default_branch }}\n\n      - uses: actions/github-script@v7\n        with:\n          script: |\n            const k = require(`${process.env.GITHUB_WORKSPACE}/.github/kban/resolve.js`);\n            const ctx = { github, context, core };\n            const p = context.payload;\n            switch (context.eventName) {\n              case \"pull_request\": {\n                const pr = p.pull_request;\n                if (p.action === \"closed\") {\n                  if (pr.merged) await k.moveFromPr(ctx, pr, \"done\");\n                } else {\n                  await k.moveFromPr(ctx, pr, \"testing\", { key: \"pr\", value: pr.html_url });\n                }\n                break;\n              }\n              case \"workflow_run\": {\n                if (p.workflow_run.conclusion !== \"success\" || p.workflow_run.event !== \"pull_request\") break;\n                await k.moveFromPr(ctx, await k.prFromSha(ctx, p.workflow_run.head_sha), \"deploying\");\n                break;\n              }\n              case \"deployment_status\": {\n                const st = p.deployment_status;\n                if (st.state !== \"success\" || /prod/i.test(p.deployment.environment || \"\")) break;\n                const url = st.environment_url || st.target_url;\n                await k.moveFromPr(ctx, await k.prFromSha(ctx, p.deployment.sha), \"verifying\", url ? { key: \"preview\", value: url } : undefined);\n                break;\n              }\n            }\n",
  ".github/workflows/kban-testflight.yml": "# kban: PR の CI が通ったら TestFlight にアップロードし、カードを「確認」に進める。\nname: kban-testflight\n\non:\n  workflow_run:\n    workflows: [kban-ci]\n    types: [completed]\n\npermissions:\n  issues: write\n  pull-requests: read\n  contents: read\n\nconcurrency:\n  group: kban-testflight\n  cancel-in-progress: false\n\njobs:\n  beta:\n    if: github.event.workflow_run.conclusion == 'success' && github.event.workflow_run.event == 'pull_request'\n    runs-on: macos-15\n    timeout-minutes: 60\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          ref: ${{ github.event.workflow_run.head_sha }}\n      - uses: ruby/setup-ruby@v1\n        with:\n          ruby-version: \"3.3\"\n      - run: gem install fastlane --no-document\n      - name: Upload to TestFlight\n        env:\n          ASC_KEY_ID: ${{ secrets.ASC_KEY_ID }}\n          ASC_ISSUER_ID: ${{ secrets.ASC_ISSUER_ID }}\n          ASC_KEY_P8: ${{ secrets.ASC_KEY_P8 }}\n          MATCH_GIT_URL: ${{ secrets.MATCH_GIT_URL }}\n          MATCH_PASSWORD: ${{ secrets.MATCH_PASSWORD }}\n          MATCH_GIT_BASIC_AUTHORIZATION: ${{ secrets.MATCH_GIT_BASIC_AUTHORIZATION }}\n          KBAN_SCHEME: ${{ vars.KBAN_SCHEME }}\n        run: fastlane beta\n      - name: kban → 確認\n        uses: actions/github-script@v7\n        with:\n          script: |\n            const fs = require(\"fs\");\n            const k = require(`${process.env.GITHUB_WORKSPACE}/.github/kban/resolve.js`);\n            const build = fs.existsSync(\"fastlane/kban_build.txt\") ? fs.readFileSync(\"fastlane/kban_build.txt\", \"utf8\").trim() : \"\";\n            const pr = await k.prFromSha({ github, context, core }, context.payload.workflow_run.head_sha);\n            await k.moveFromPr({ github, context, core }, pr, \"verifying\", { key: \"preview\", value: `TestFlight ${build}`.trim() });\n",
  "CLAUDE.kban.md": "## kban のルール(Claude Code 向け)\n\nこのリポジトリの Issue は kban(カンバン)で管理されています。`claude` ラベルの Issue を実装するときは次を守ってください。\n\n- Issue 本文の「仕様」「進め方」「受入条件」「Claude Codeへの指示」がタスクの定義です。「進め方」の順に進め、受入条件はすべて満たすこと。\n- 「前提」に挙がった Issue が未完了なら、その変更に依存しない範囲だけを実装し、残りを PR 本文に書く。\n- 作業ブランチ名は `claude/issue-<番号>-<短い説明>` にする。\n- 変更に合ったテストを追加・更新し、CI(`kban-ci`)と同じコマンドが手元で通ることを確認する。\n  - Web: `npm ci && npm run lint --if-present && npm test --if-present && npm run build --if-present`\n  - iOS: `xcodebuild test -scheme <scheme> -destination 'platform=iOS Simulator,name=iPhone 16'`\n- 完了したら `gh pr create` で PR を作る。本文には必ず次を書く。\n  - `Closes #<Issue番号>`(kban がカードを追うのに使います)\n  - 進め方の各ステップと受入条件ごとの結果(チェックリスト)\n  - 実行したテストと結果\n  - 人が確認する手順(画面のどこを、何を見ればよいか)\n- `@claude` で差し戻しコメントが来たら、同じ PR のブランチに追加コミットする。新しい PR は作らない。\n- 仕様にない大きな変更や依存追加が必要なら、実装せず Issue にコメントで相談する。\n",
  "fastlane/Fastfile": "# kban: TestFlight へのアップロード(CI 用)\n# 署名は fastlane match(appstore, readonly)を使います。最初に手元で `fastlane match appstore` を一度実行してください。\ndefault_platform(:ios)\n\nplatform :ios do\n  lane :beta do\n    setup_ci\n    api_key = app_store_connect_api_key(\n      key_id: ENV[\"ASC_KEY_ID\"],\n      issuer_id: ENV[\"ASC_ISSUER_ID\"],\n      key_content: ENV[\"ASC_KEY_P8\"],\n      is_key_content_base64: false\n    )\n    match(type: \"appstore\", readonly: true, api_key: api_key)\n\n    scheme = ENV[\"KBAN_SCHEME\"].to_s.empty? ? JSON.parse(File.read(\"../.github/kban/config.json\"))[\"scheme\"] : ENV[\"KBAN_SCHEME\"]\n    build = latest_testflight_build_number(api_key: api_key) + 1\n    increment_build_number(build_number: build)\n\n    build_app(scheme: scheme, export_method: \"app-store\")\n    upload_to_testflight(api_key: api_key, skip_waiting_for_build_processing: true)\n\n    version = get_version_number(target: scheme) rescue \"\"\n    File.write(\"kban_build.txt\", \"#{version} (#{build})\")\n  end\nend\n"
};
